<script setup lang="ts">
import type { BsPlanningCopy, BsPlanningForm, BsPlanningPicker, BsPlanningRow, BsPlanningPriceRow, BsPlanningView } from '../types/supplyPlanningPresentation'
type PickerKind='product'|'supplier'|'bin'|'reel'
const props=defineProps<{copy:BsPlanningCopy;view:BsPlanningView;rows:BsPlanningRow[];priceRows:BsPlanningPriceRow[];pickers:Record<PickerKind,BsPlanningPicker>}>()
const mode=defineModel<'bin'|'position'|'supplier'|'prices'>('mode',{required:true}),search=defineModel<string>('search',{required:true}),page=defineModel<number>('page',{required:true}),historyPage=defineModel<number>('historyPage',{required:true}),priceProduct=defineModel<string>('priceProduct',{required:true}),priceVendor=defineModel<string>('priceVendor',{required:true})
const editorOpen=defineModel<boolean>('editorOpen',{required:true}),historyOpen=defineModel<boolean>('historyOpen',{required:true}),form=defineModel<BsPlanningForm>('form',{required:true})
const emit=defineEmits<{retry:[];retryHistory:[];add:[];edit:[id:string];history:[id:string];submit:[];product:[id:string];reel:[id:string];pickerSearch:[kind:PickerKind,query:string];pickerMore:[kind:PickerKind];pickerRetry:[kind:PickerKind]}>()
function change<K extends keyof BsPlanningForm>(key:K,value:BsPlanningForm[K]){form.value={...form.value,[key]:value}}
function entity(kind:PickerKind,value:string){if(kind==='product')emit('product',value);else if(kind==='reel')emit('reel',value);else change(kind==='bin'?'binId':'vendorId',value)}
const entityFields=computed(()=>props.view.editor.kind==='bin'?[]:props.view.editor.kind==='position'?[{kind:'product' as const,label:props.copy.product,value:form.value.productId,locked:props.view.editor.identityLocked},{kind:'bin' as const,label:props.copy.bin,value:form.value.binId,locked:false},{kind:'reel' as const,label:props.copy.reel,value:form.value.reelId,locked:props.view.editor.identityLocked||!form.value.productId}]:[{kind:'product' as const,label:props.copy.product,value:form.value.productId,locked:props.view.editor.identityLocked},{kind:'supplier' as const,label:props.copy.supplier,value:form.value.vendorId,locked:props.view.editor.identityLocked}])
const columns=computed(()=>[ {key:'primary',field:'primary',header:mode.value==='bin'?props.copy.code:props.copy.product},{key:'secondary',field:'secondary',header:mode.value==='bin'?props.copy.name:mode.value==='supplier'?props.copy.supplier:props.copy.code},...(mode.value==='supplier'?[{key:'itemCode',field:'itemCode',header:props.copy.itemCode},{key:'unit',field:'unit',header:props.copy.unit},{key:'lead',field:'lead',header:props.copy.lead},{key:'review',field:'review',header:props.copy.review},{key:'preferred',field:'preferred',header:props.copy.preferred}]:[{key:'position',field:'position',header:props.copy.bin}]),{key:'status',field:'status',header:props.copy.active},{key:'actions',header:props.copy.history}])
const priceColumns=computed(()=>[{key:'invoice',header:props.copy.invoice},{key:'product',field:'product',header:props.copy.product},{key:'supplier',field:'supplier',header:props.copy.supplier},{key:'quantity',field:'quantity',header:props.copy.quantity},{key:'unit',field:'unit',header:props.copy.unit},{key:'cost',field:'cost',header:props.copy.cost},{key:'baseQuantity',field:'baseQuantity',header:props.copy.baseQuantity},{key:'baseUnit',field:'baseUnit',header:props.copy.baseUnit},{key:'baseCost',field:'baseCost',header:props.copy.baseCost},{key:'total',field:'total',header:props.copy.total},{key:'currency',field:'currency',header:props.copy.currency},{key:'date',field:'date',header:props.copy.date},{key:'status',field:'status',header:props.copy.status}])
const historyColumns=computed(()=>[{key:'revision',field:'revision',header:props.copy.revision},{key:'reason',field:'reason',header:props.copy.reason},{key:'changes',field:'changes',header:props.copy.changes},{key:'actor',field:'actor',header:props.copy.actor},{key:'date',field:'date',header:props.copy.date}])
</script>
<template>
 <BsStack gap="lg">
  <BsPageHeader :title="copy.title" :subtitle="copy.subtitle"><template #actions><BsLink v-if="view.available" :to="view.reorderTo">{{ copy.reorder }}</BsLink><BsButton v-if="view.available && view.canManage" :disabled="view.locked || editorOpen || historyOpen" @click="emit('add')">{{ copy.add }}</BsButton></template></BsPageHeader>
  <BsPanel v-if="!view.available" padding="md"><BsText as="p">{{ copy.noShop }}</BsText></BsPanel>
  <BsStack v-else gap="md">
   <BsSelect :model-value="mode" :label="copy.mode" :options="view.modes" option-label="label" option-value="value" :disabled="view.locked || editorOpen || historyOpen" @update:model-value="mode = String($event) as typeof mode" />
   <template v-if="mode === 'prices'">
    <BsText as="p" tone="muted">{{ copy.priceNotice }}</BsText>
    <BsGrid :columns="2"><BsEntityPicker :model-value="priceProduct" :label="copy.product" :options="[{id:'',name:copy.allProducts},...pickers.product.options]" option-label="name" option-value="id" :loading="pickers.product.loading" :error="pickers.product.error" :has-more="pickers.product.hasMore" :load-more-label="pickers.product.more" :retry-label="pickers.product.retry" @search="emit('pickerSearch','product',$event)" @load-more="emit('pickerMore','product')" @retry="emit('pickerRetry','product')" @update:model-value="priceProduct=String($event??'')" /><BsEntityPicker :model-value="priceVendor" :label="copy.supplier" :options="[{id:'',name:copy.allSuppliers},...pickers.supplier.options]" option-label="name" option-value="id" :loading="pickers.supplier.loading" :error="pickers.supplier.error" :has-more="pickers.supplier.hasMore" :load-more-label="pickers.supplier.more" :retry-label="pickers.supplier.retry" @search="emit('pickerSearch','supplier',$event)" @load-more="emit('pickerMore','supplier')" @retry="emit('pickerRetry','supplier')" @update:model-value="priceVendor=String($event??'')" /></BsGrid>
    <BsDataTable :value="priceRows" :label="copy.prices" :columns="priceColumns" data-key="id" :loading="view.loading" :error="view.error || null" lazy paginator :rows="20" :first="(page-1)*20" :total-records="view.total" @page="page=$event.page+1" @retry="emit('retry')"><template #cell-invoice="{row}"><BsLink :to="row.to">{{ row.invoice }}</BsLink></template><template #empty><BsText as="p">{{ copy.empty }}</BsText></template></BsDataTable>
   </template>
   <BsDataTable v-else :value="rows" :label="mode === 'bin' ? copy.bins : mode === 'position' ? copy.positions : copy.suppliers" :columns="columns" data-key="id" :loading="view.loading" :error="view.error || null" searchable :search-label="copy.search" lazy paginator :rows="20" :first="(page-1)*20" :total-records="view.total" @search="search=$event" @page="page=$event.page+1" @retry="emit('retry')"><template #cell-actions="{row}"><BsInline wrap><BsButton v-if="view.canManage" variant="secondary" :disabled="view.locked || editorOpen || historyOpen" @click="emit('edit',row.id)">{{ copy.edit }}</BsButton><BsButton variant="text" :disabled="view.locked || editorOpen || historyOpen" @click="emit('history',row.id)">{{ copy.history }}</BsButton></BsInline></template><template #empty><BsText as="p">{{ copy.empty }}</BsText></template></BsDataTable>
  </BsStack>
  <BsRecordActionDialog v-model:visible="editorOpen" :title="view.editor.title" :dirty="view.editor.dirty" :pending="view.editor.pending" :close-blocked="view.locked" :error="view.editor.error" :submit-label="copy.save" :cancel-label="copy.cancel" pinned-actions size="lg" @submit="emit('submit')">
   <BsText as="p" tone="muted">{{ view.editor.notice }}</BsText>
   <template v-if="view.editor.kind === 'bin'">
    <BsGrid :columns="2"><BsField v-slot="f" for="planning-bin-code" :label="copy.code"><BsInput :id="f.id" :model-value="form.code" :disabled="view.locked" required :maxlength="40" @update:model-value="change('code',String($event))" /></BsField><BsField v-slot="f" for="planning-bin-name" :label="copy.name"><BsInput :id="f.id" :model-value="form.name" :disabled="view.locked" required :maxlength="120" @update:model-value="change('name',String($event))" /></BsField><BsField v-slot="f" for="planning-bin-aisle" :label="copy.aisle"><BsInput :id="f.id" :model-value="form.aisle" :disabled="view.locked" :maxlength="80" @update:model-value="change('aisle',String($event))" /></BsField><BsField v-slot="f" for="planning-bin-shelf" :label="copy.shelf"><BsInput :id="f.id" :model-value="form.shelf" :disabled="view.locked" :maxlength="80" @update:model-value="change('shelf',String($event))" /></BsField></BsGrid>
   </template>
   <BsEntityPicker v-for="field in entityFields" :key="field.kind" :model-value="field.value" :label="field.label" :options="pickers[field.kind].options" option-label="name" option-value="id" :loading="pickers[field.kind].loading" :error="pickers[field.kind].error" :has-more="pickers[field.kind].hasMore" :load-more-label="pickers[field.kind].more" :retry-label="pickers[field.kind].retry" :disabled="view.locked || field.locked" @search="emit('pickerSearch',field.kind,$event)" @load-more="emit('pickerMore',field.kind)" @retry="emit('pickerRetry',field.kind)" @update:model-value="entity(field.kind,String($event??''))" />
   <BsField v-if="view.editor.kind === 'position'" v-slot="f" for="planning-position-notes" :label="copy.notes"><BsTextarea :id="f.id" :model-value="form.notes" :disabled="view.locked" :maxlength="500" @update:model-value="change('notes',String($event))" /></BsField>
   <template v-if="view.editor.kind === 'supplier'">
    <BsField v-slot="f" for="planning-supplier-code" :label="copy.itemCode"><BsInput :id="f.id" :model-value="form.itemCode" :disabled="view.locked" required :maxlength="120" @update:model-value="change('itemCode',String($event))" /></BsField>
    <BsField v-slot="f" for="planning-supplier-unit" :label="copy.unit"><BsSelect :input-id="f.id" :model-value="form.unit" :label="copy.unit" :options="view.editor.units" option-label="label" option-value="value" :disabled="view.locked || !form.productId || view.editor.unitLoading" :loading="view.editor.unitLoading" @update:model-value="change('unit',String($event??''))" /></BsField>
    <BsGrid :columns="2"><BsField v-slot="f" for="planning-supplier-lead" :label="copy.lead"><BsInput :id="f.id" :model-value="form.leadDays" inputmode="numeric" :disabled="view.locked" required @update:model-value="change('leadDays',String($event))" /></BsField><BsField v-slot="f" for="planning-supplier-review" :label="copy.review"><BsInput :id="f.id" :model-value="form.reviewDays" inputmode="numeric" :disabled="view.locked" required @update:model-value="change('reviewDays',String($event))" /></BsField></BsGrid>
    <BsCheckbox :model-value="form.preferred" :label="copy.preferred" :disabled="view.locked" @update:model-value="change('preferred',Boolean($event))" />
   </template>
   <BsCheckbox :model-value="form.active" :label="copy.active" :disabled="view.locked" @update:model-value="change('active',Boolean($event))" />
   <BsField v-slot="f" for="planning-change-reason" :label="copy.reason"><BsTextarea :id="f.id" :model-value="form.reason" :disabled="view.locked" required :minlength="3" :maxlength="500" @update:model-value="change('reason',String($event))" /></BsField>
  </BsRecordActionDialog>
  <BsDialog v-model:visible="historyOpen" :title="view.history.title" size="lg">
   <BsText v-if="view.history.loading" role="status">{{ copy.retry }}</BsText><BsStack v-else-if="view.history.error"><BsText role="alert">{{ view.history.error }}</BsText><BsButton @click="emit('retryHistory')">{{ copy.retry }}</BsButton></BsStack>
   <BsStack v-else gap="md"><BsDescriptionList><BsDescriptionItem v-for="field in view.history.fields" :key="field.label" :term="field.label">{{ field.value }}</BsDescriptionItem></BsDescriptionList><BsDataTable :value="view.history.events" :label="copy.history" :columns="historyColumns" data-key="id" lazy paginator :rows="20" :first="(historyPage-1)*20" :total-records="view.history.total" @page="historyPage=$event.page+1" /></BsStack>
   <template #footer><BsButton @click="historyOpen=false">{{ copy.close }}</BsButton></template>
  </BsDialog>
 </BsStack>
</template>
